def save_review():
    assert len(cases)==len({r['id'] for r in cases})==108
    obj={'reviewer':'Codex assistant visual/text assessment, not independently human adjudicated',
      'mask_key_opened_before_saving':False,'policy':'Known geometry controls have no physical object/state changes. Illumination claims and identity differences separate. Conservative about apparent frame-coordinate motion, cropped visibility and unresolved anatomy. Natural facts locked in eval_rubric before candidate outputs.',
      'limits':'Procedural masking only; wording may reveal training. Adaptive development images, one seed. Relative pair scores do not imply generally correct captions.',
      'cases':cases}
    (ROOT/'masked_assessments.json').write_text(json.dumps(obj,ensure_ascii=False,indent=2)+'\n',encoding='utf8')

if __name__=='__main__':save_review()
